const TZ = 'America/Cuiaba';
// chaves do Redis vêm com o número do WhatsApp, que pode ter ou não o 9 depois do DDD: acha pelos 8 últimos dígitos
const chaves = (j) => [].concat(j?.keys || Object.keys(j || {})).map(String);
const pausas = chaves($('Pausas').first().json);
const memorias = chaves($('Memórias').first().json);
const achar = (lista, prefixo, tel) => lista.find((k) => k.startsWith(prefixo + tel.slice(0, 4)) && k.endsWith(tel.slice(-8)));
const agora = new Date().toLocaleString('pt-BR', { timeZone: TZ, weekday: 'long', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const quem = { cliente: 'Cliente', ia: 'Você (IA)', humano: ('' + $('Loja').first().json.dona + '') };
return $('Quem retomar').all().map((i) => i.json).filter((c) => c.cliente_id).filter((c) => !achar(pausas, ('' + $('Loja').first().json.empresa_id + ':pausa:'), c.telefone)).map((c) => {
  const nome = String(c.nome || '').trim().split(/\s+/)[0] || '';
  const conversa = (c.historico || []).map((m) => '[' + m.em + '] ' + (quem[m.autor] || m.autor) + (m.tipo !== 'texto' ? ' (' + m.tipo + ')' : '') + ': ' + m.texto).join('\n');
  const ultima = c.tentativa >= c.total;
  const instrucao = [
    ('Você é a assistente virtual da ' + $('Loja').first().json.dona + ', do salão ' + $('Loja').first().json.nome + ' (' + $('Loja').first().json.cidade + '-MT), no WhatsApp do salão.'),
    'A conversa abaixo parou: a última mensagem foi sua e a cliente' + (nome ? ' (' + nome + ')' : '') + ' não respondeu. Agora é ' + agora + '.',
    'Esta é a tentativa ' + c.tentativa + ' de ' + c.total + ' de retomar a conversa' + (ultima ? ' (a última: depois dela você não manda mais nada).' : '.'),
    c.resumo_ia ? 'Resumo do que se sabe dela: ' + c.resumo_ia : '',
    '', 'CONVERSA (mais antiga primeiro):', conversa, '',
    'O QUE ELA FALOU POR ÚLTIMO: ' + (c.historico || []).filter((m) => m.autor === 'cliente').slice(-3).map((m) => '"' + m.texto + '"').join(' / '), '',
    'Primeiro decida se faz sentido retomar. Responda exatamente "PULAR: <motivo curto>" se:',
    '- a conversa terminou de forma natural (ela agradeceu, se despediu ou disse "ok, obrigada" sem nada pendente);',
    '- ela disse que não quer, não tem interesse, vai procurar outro lugar ou pediu para não mandar mensagem;',
    ('- quem está devendo resposta é o salão (você disse que ia confirmar com a ' + $('Loja').first().json.dona + ', ou a ' + $('Loja').first().json.dona + ' assumiu a conversa);'),
    '- o horário já está marcado e não há nada pendente;',
    // prompt v5.7/v5.8: impedimento temporário é adiamento, e "não crie retorno automático sem autorização da cliente"
    '- ela disse que precisa esperar um tempo antes de vir (cirurgia/recuperação, viagem, compromisso, "volto depois", "semana que vem") — respeite: o alô automático soaria como cobrança;',
    ('- sua última mensagem ofereceu encaminhar o pedido ou perguntar algo para a ' + $('Loja').first().json.dona + ' e ela não respondeu: repetir a oferta é insistência;'),
    ('- sua última mensagem disse que pediu orçamento ou perguntou algo à ' + $('Loja').first().json.dona + ' e está esperando a resposta dela: quem deve o retorno é o salão;'),
    '- sua última mensagem não deixou nada em aberto e retomar seria só insistência.',
    'NÃO pule quando ela só cumprimentou ("oi", "boa noite", "olá") e sumiu sem dizer o que queria: muita cliente chega por anúncio assim. Nesse caso retome.',
    'Se fizer sentido, escreva a mensagem como uma pessoa de verdade que atende o WhatsApp do salão e lembrou dessa conversa:',
    // só cumprimento: não há assunto dela para retomar; um alô leve perguntando o que ela procura
    !(c.historico || []).some((m) => m.autor === 'cliente' && !/^\W*(oi+|ol[aá]|opa|e a[ií]|bo[am] (dia|tarde|noite)|tudo bem|td bem|tudo bom)[\s!?.,🙂😊]*$/i.test(String(m.texto || '').trim()))
      ? (c.tentativa === 1
        ? '- ela só cumprimentou e ainda não disse o que procura. Mande um alô leve e curto, puxando o assunto do salão de mega hair sem listar serviços: pergunte de um jeito simples o que ela está procurando ou se quer saber sobre mega hair. Não se apresente de novo e não repita o cumprimento que você já mandou;'
        : '- você JÁ mandou um alô antes. NÃO repita nem reformule esse alô e não cumprimente de novo. Uma frase curta e diferente, deixando a porta aberta para quando ela quiser saber sobre mega hair, sem cobrar resposta;')
      : c.tentativa === 1
      ? '- fale do assunto DELA, com o detalhe que ela trouxe (a fita adesiva, o loiro, os 60 cm, a primeira vez, as fotos que você mandou...), e pergunte de um jeito simples se ficou alguma dúvida sobre isso ou o que ela achou. O objetivo é só saber se ficou dúvida: não convide para agendar nem para a avaliação (a não ser que ela mesma já tenha falado em marcar) e não faça de novo a sua última pergunta com outras palavras; varie o começo (nem sempre "Oi, nome!": pode ir direto ao assunto);'
      : '- você JÁ mandou um alô antes (é a sua última mensagem na conversa). NÃO repita nem reformule esse alô, não pergunte de novo se ficou dúvida e não cumprimente de novo. Escreva só uma frase curta e diferente da anterior, ligada ao assunto dela, deixando a porta aberta sem cobrar resposta (a ideia é "quando quiser ver isso, é só me chamar"; não copie essas palavras);',
    '- faça UMA coisa só nesta mensagem: uma pergunta simples ou um pedido, nunca os dois; não peça foto e pergunte sobre dúvida juntos;',
    '- NÃO repita nem reformule a pergunta que ficou sem resposta, e não explique de novo o que já foi explicado;',
    '- nada de frase pronta de robô: "Se precisar de ajuda, estou por aqui", "Fico à disposição", "Qualquer dúvida estou à disposição", "Só passando pra lembrar", "Espero que esteja bem", "é só me chamar", "é só me dar um alô";',
    // regras do prompt da a dona que valem também para o alô (conversa da Grazi, 30–31/10)
    '- use só o que está escrito na conversa: não suponha o que ela não disse (se ela não respondeu se é a primeira vez, não diga que é);',
    ('- não indique técnica, quantidade nem tipo de cabelo, e não ofereça "explicar qual técnica a ' + $('Loja').first().json.dona + ' recomenda": quem define isso é a ' + $('Loja').first().json.dona + ' na avaliação;'),
    '- não afirme estoque, cor ou textura disponível, nem resultado ("tem uns pretos lindos", "temos aqui no salão", "tem liso e ondulado", "ia ficar perfeito em você"); o catálogo é do fornecedor: fale dele só como catálogo, sem dizer que o salão tem aquele cabelo;',
    '- sem exagero nem superlativo ("maravilhoso", "lindíssimo", "um mais lindo que o outro", "perfeito");',
    // conversa da Claudineia (08/11): o alô falou em "preencher essas falhas"
    ('- nunca diga que o mega preenche falhas, recupera, resolve a queda ou devolve o volume: isso depende do fio e quem vê é a ' + $('Loja').first().json.dona + ';'),
    '- não sugira dia nem plano que ela não mencionou ("aproveitar o sábado", "passar aqui hoje");',
    '- se ela já disse que usa mega ou conhece a técnica, nada de explicação de iniciante;',
    ('- não prometa passar foto ou mensagem para a ' + $('Loja').first().json.dona + ' nem que ela vai dar retorno (o alô não encaminha nada);'),
    ('- 1 frase (no máximo 2), jeito de WhatsApp de ' + $('Loja').first().json.cidade + ' ("pra", "tá"), sem formalidade; sem cobrança, culpa, urgência ou promoção inventada;'),
    '- não invente situação nem contexto ("o dia tá corrido", "lembrei de você", promoção, novidade); não comece com "Oi" se você já cumprimentou nesta conversa;',
    ('- não ofereça fotos de resultados ou de clientes da ' + $('Loja').first().json.dona + ' (não existem; só há fotos de cabelo do catálogo do fornecedor);'),
    '- não fale preço nem valor (nem repita um que esteja na conversa); não invente horário livre, estoque nem resultado; não diga que ela respondeu nem que você "viu" algo novo;',
    '- sem negrito, sem lista; emoji só se combinar, no máximo um; o primeiro nome no máximo uma vez, se souber;',
    '- não fale de tempo sem resposta.',
    'Responda só com a mensagem (ou com PULAR: motivo), sem aspas.',
  ].filter((l) => l !== null).join('\n');
  // memória da IA: a chave que já existe; sem ela, o formato do WhatsApp (sem o 9)
  const memoria = achar(memorias, ('' + $('Loja').first().json.empresa_id + ':memoria:'), c.telefone) || ('' + $('Loja').first().json.empresa_id + ':memoria:') + c.telefone.replace(/^(55\d{2})9(\d{8})$/, '$1$2');
  return { json: { ...c, nome, instrucao, memoria, historico: undefined } };
});

const prep = $('Preparar').all();
return $input.all().map((r, i) => {
  const c = prep[i].json;
  let t = String(r.json.candidates?.[0]?.content?.parts?.filter((p) => !p.thought).map((p) => p.text || '').join('') || '').trim();
  t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^["“]|["”]$/g, '').trim();
  // sem resposta do Gemini: não grava nada, tenta de novo na próxima rodada
  if (!t) return { json: { ...c, acao: 'erro' } };
  const pular = t.match(/^PULAR\s*:?\s*(.*)$/is);
  if (pular) return { json: { ...c, acao: 'pular', motivo: pular[1].trim().slice(0, 300) || 'sem motivo' } };
  return { json: { ...c, acao: 'enviar', texto: t } };
});

// Ficha da loja deste atendimento (motor único). Tudo o que muda de uma loja para outra sai daqui.
const bruto = $('Entrada do motor').first().json.loja_json;
const f = typeof bruto === 'string' ? JSON.parse(bruto || 'null') : bruto;
if (!f || !f.empresa_id) return [];
const sem9 = (n) => { const d = String(n).replace(/\D/g, ''); return /^55\d{2}9\d{8}$/.test(d) ? d.slice(0, 4) + d.slice(5) : d; };
const lista = (v) => (Array.isArray(v) ? v : String(v || '').split(',')).map((s) => String(s).trim()).filter(Boolean);
const dona = String(f.dona || 'responsável').trim();
// Trava de teste: números com e sem o 9 (o principal compara como o WhatsApp manda; as rotinas, sem o 9).
// Loja ainda não liberada pela agência (config.ia.liberada) e sem lista: ninguém recebe, só a dona.
let permitidos = [...new Set(lista(f.permitidos).flatMap((n) => [n.replace(/\D/g, ''), sem9(n)]).filter(Boolean))];
if (f.liberada !== true && !permitidos.length) permitidos = ['0'];
if (f.liberada === true) permitidos = [];
return [{ json: {
  empresa_id: f.empresa_id, nome: f.nome || '', nicho: f.nicho || '', instancia: f.instancia || '',
  dona, dona_maiuscula: dona.toUpperCase(), nome_maiusculo: String(f.nome || '').toUpperCase(), cidade: f.cidade || '', fuso: f.fuso || 'America/Cuiaba',
  assist: lista(f.assist).join(','), assist_sem9: lista(f.assist).map(sem9).join(','),
  permitidos: permitidos.join(','), catalogo_link: f.catalogo_link || '',
  // tempo mínimo que cada cliente ocupa na agenda (config.ia.bloco_min); 0 = vale o tempo de cada serviço
  bloco_min: Number.isInteger(Number(f.bloco_min)) && Number(f.bloco_min) >= 30 && Number(f.bloco_min) <= 480 ? Number(f.bloco_min) : 0,
  // a ficha passa de um workflow para outro (loja_json) e é lida de novo por este mesmo código: liberada vai junto
  liberada: f.liberada === true,
  // teto de conversas do mês (supabase/048): no_limite = a loja chegou ao teto; conversa_barrada = além disso,
  // quem mandou esta mensagem ainda não falou com a IA hoje (conversa nova)
  limite_mes: f.limite_mes ?? null, uso_mes: f.uso_mes ?? null, no_limite: f.no_limite === true, conversa_barrada: f.conversa_barrada === true,
} }];
